      "marital_status": "{maritalStatus}",
      "religion": "{religion}",
      "ethnicity": "{ethnicity}"
    },
    smsFormat: 'details#education#profession#maritalStatus#religion#ethnicity',
    successMessage: '✅ Profile completed! Now tell us about yourself.',
    showInConversation: true
  },
  {
    id: 4,
    title: 'Describe Yourself',
    subtitle: 'What makes you special?',
    description: 'Share a brief description of your personality',
    icon: '💭',
