    inputType: 'text',
    inputLabel: 'Describe Yourself',
    inputPlaceholder: 'e.g., Hardworking, honest, family-oriented, loves nature',
    defaultInput: 'Hardworking, honest, and family-oriented man who loves nature',
    requiresPhone: true,
    defaultPhone: '0712345678',
    bodyTemplate: { "description": "{input}" },
    smsFormat: 'MYSELF description',
    successMessage: '🎉 You are now registered for dating! Start searching for your perfect match.',
    showInConversation: true
  },
  {
    id: 5,
    title: 'Find Your Match',
    subtitle: 'Search for your perfect partner',
    description: 'Search for matches by age range and location',
    icon: '❤️',
    userMessage: 'You send:',
    systemMessage: 'System replies:',
    endpoint: '/sms',
    method: 'POST',
    inputType: 'form',
    inputLabel: 'Search Criteria',
    requiresPhone: true,
    defaultPhone: '0712345678',
    fields: [
      { key: 'age_range', label: '📅 Age Range', placeholder: '26-30', required: true },
      { key: 'town', label: '📍 Town/City', placeholder: 'Nairobi', required: true }
    ],
    bodyTemplate: {
      "phone_number": "{phone}",
      "message": "match#{age_range}#{town}"
    },
    smsFormat: 'match#age_range#town',
    successMessage: '🔍 Matches found! View your matches below.',
    showInConversation: true
  }
];

function App() {
  // Core state
  const [currentStep, setCurrentStep] = useState(0);
  const [completedSteps, setCompletedSteps] = useState(new Set());
  const [formData, setFormData] = useState({});
  const [isLoading, setIsLoading] = useState(false);

  // Response state
  const [responseData, setResponseData] = useState(null);
  const [responseStatus, setResponseStatus] = useState(null);
  const [responseMessage, setResponseMessage] = useState('');
  const [isSuccess, setIsSuccess] = useState(false);

  // SMS Conversation state
  const [smsConversation, setSmsConversation] = useState([]);
  const [history, setHistory] = useState([]);
  const [historyLoaded, setHistoryLoaded] = useState(false);

  // User state
  const [currentUser, setCurrentUser] = useState(null);
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [showWelcome, setShowWelcome] = useState(false);
  const [welcomeMessage, setWelcomeMessage] = useState('');

  // Dashboard state
  const [matches, setMatches] = useState([]);
  const [currentMatchIndex, setCurrentMatchIndex] = useState(0);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState('');
  const [activeTab, setActiveTab] = useState('discover');
  const [showProfile, setShowProfile] = useState(false);
  const [showMatchDetails, setShowMatchDetails] = useState(false);
  const [notifications, setNotifications] = useState([]);
  const [incomingRequests, setIncomingRequests] = useState([]);
  const [interests, setInterests] = useState([]);

  // Load saved state
  useEffect(() => {
    try {
      const savedState = localStorage.getItem('penziUserState');
      if (savedState) {
        const parsed = JSON.parse(savedState);
        setCurrentStep(parsed.currentStep || 0);
        setCompletedSteps(new Set(parsed.completedSteps || []));
        setHistory(parsed.history || []);
        setSmsConversation(parsed.smsConversation || []);
        setHistoryLoaded(true);

        if (parsed.currentUser) {
          setCurrentUser(parsed.currentUser);
          setIsLoggedIn(true);
        }
        if (parsed.welcomeMessage) {
          setWelcomeMessage(parsed.welcomeMessage);
        }
      }
    } catch (e) {
      console.warn('Could not load saved state:', e);
    }
  }, []);

  // Save state
  useEffect(() => {
    if (!historyLoaded) return;
    try {
      const stateToSave = {
        currentStep,
        completedSteps: Array.from(completedSteps),
        formData,
        history: history.slice(-50),
        smsConversation,
        currentUser,
        welcomeMessage
      };
      localStorage.setItem('penziUserState', JSON.stringify(stateToSave));
    } catch (e) {
      console.warn('Could not save state:', e);
    }
  }, [currentStep, completedSteps, formData, history, smsConversation, currentUser, welcomeMessage, historyLoaded]);

  // Initialize form data
  useEffect(() => {
    const step = CONVERSATION_STEPS[currentStep];
    const initialData = {};

    if (step.requiresPhone) {
      initialData.phone = step.defaultPhone || '0712345678';
    }
    if (step.fields) {
      step.fields.forEach(field => {
        initialData[field.key] = '';
      });
    }
    if (step.defaultInput) {
      initialData.input = step.defaultInput;
    }

    setFormData(prev => ({ ...prev, ...initialData }));

    // Show saved response
    const savedResponse = history.find(h => h.step === currentStep);
    if (savedResponse) {
      setResponseData(savedResponse.response);
      setResponseStatus(savedResponse.status);
      setResponseMessage(savedResponse.message || '');
      setIsSuccess(savedResponse.success || false);
    } else {
      setResponseData(null);
      setResponseStatus(null);
      setResponseMessage('');
      setIsSuccess(false);
    }
  }, [currentStep, history]);

  const handleInputChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  // Add to SMS conversation
  const addToConversation = (sender, message, isSystem = false) => {
    const entry = {
      id: Date.now(),
      sender: sender,
      message: message,
      isSystem: isSystem,
      timestamp: new Date().toLocaleTimeString()
    };
    setSmsConversation(prev => [...prev, entry]);
  };

  // Build SMS message
  const buildSmsMessage = (step) => {
    if (!step.fields && step.inputType !== 'text') return '';

    if (step.inputType === 'text') {
      const inputValue = formData.input || step.defaultInput || '';
      if (step.smsFormat) {
        return step.smsFormat.replace('description', inputValue);
      }
      return inputValue;
    }

    if (step.fields) {
      if (step.smsFormat) {
        let message = step.smsFormat;
        step.fields.forEach(field => {
          message = message.replace(`{${field.key}}`, formData[field.key] || '');
        });
        return message;
      }

      const parts = [];
      step.fields.forEach(field => {
        const value = formData[field.key] || '';
        if (value) parts.push(value);
      });
      return parts.join('#');
    }

    return '';
  };

  // Execute API
  const executeApi = async () => {
    const step = CONVERSATION_STEPS[currentStep];
    setIsLoading(true);
    setResponseStatus(null);
    setResponseMessage('');
    setIsSuccess(false);

    try {
      let endpoint = step.endpoint;
      let phone = formData.phone || step.defaultPhone || '';

      // Replace placeholders
      if (step.requiresPhone) {
        endpoint = endpoint.replace('{phone}', phone);
      }

      // Build URL
      let fullUrl = API_BASE + endpoint;

      // Build body
      let body = null;
      if (step.bodyTemplate) {
        body = { ...step.bodyTemplate };
        Object.keys(body).forEach(key => {
          let value = body[key];
          Object.keys(formData).forEach(fieldKey => {
            if (typeof value === 'string') {
              value = value.replace(`{${fieldKey}}`, formData[fieldKey] || '');
            }
          });
          if (typeof value === 'string' && value.includes('{input}')) {
            value = value.replace('{input}', formData.input || step.defaultInput || '');
          }
          body[key] = value;
        });
      }

      // Execute request
      const options = {
        method: step.method,
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        }
      };

      if (body && (step.method === 'POST' || step.method === 'PUT')) {
        options.body = JSON.stringify(body);
      }

      const startTime = Date.now();
      const response = await fetch(fullUrl, options);
      const endTime = Date.now();
      const duration = endTime - startTime;

      let responseData;
      const contentType = response.headers.get('content-type');
      if (contentType && contentType.includes('application/json')) {
        responseData = await response.json();
      } else {
        responseData = await response.text();
      }

      const result = {
        status: response.status,
        statusText: response.statusText,
        duration: duration,
        url: fullUrl,
        data: responseData,
        success: response.ok
      };

      setResponseData(result);
      setResponseStatus(response.ok ? 'success' : 'error');

      let successMsg = '';
      if (response.ok) {
        // Handle special case for activation
        if (step.id === 1) {
          const welcomeMsg = responseData?.message || step.welcomeMessage;
          setWelcomeMessage(welcomeMsg);
          successMsg = step.successMessage;
          setResponseMessage(successMsg);
          setIsSuccess(true);
          addToConversation('📱 You', 'PENZI', false);
          addToConversation('🤖 System', welcomeMsg, true);
          setShowWelcome(true);
          setCompletedSteps(prev => new Set([...prev, currentStep]));
        } else {
          successMsg = step.successMessage;
          setResponseMessage(successMsg);
          setIsSuccess(true);

          const userMessage = buildSmsMessage(step);
          if (step.showInConversation !== false && userMessage) {
            addToConversation('📱 You', userMessage, false);
            addToConversation('🤖 System', successMsg, true);
          }

          setCompletedSteps(prev => new Set([...prev, currentStep]));

          // If registration complete, login user
          if (step.id === 4 && response.ok) {
            const user = {
              phone: formData.phone || step.defaultPhone || '0712345678',
              name: formData.name || 'User'
            };
            setCurrentUser(user);
            setIsLoggedIn(true);
            addNotification('🎉 Welcome to PENZI! Start finding your perfect match today.');
          }

          // If matches found, store them
          if (step.id === 5 && responseData) {
            setMatches(responseData.matches || []);
            if (responseData.matches && responseData.matches.length > 0) {
              addNotification(`❤️ Found ${responseData.matches.length} matches!`);
            }
          }
        }
      } else if (!response.ok) {
        const errorMsg = responseData?.message || responseData?.error || `Error ${response.status}: ${response.statusText}`;
        setResponseMessage(errorMsg);
        setIsSuccess(false);
      }

      saveToHistory(currentStep, result, response.ok ? 'success' : 'error', successMsg, response.ok);

    } catch (error) {
      const errorResult = {
        status: 0,
        statusText: 'Network Error',
        duration: 0,
        url: API_BASE + step.endpoint,
        data: { 
          error: error.message, 
          details: 'Please make sure the server is running at ' + API_BASE 
        },
        success: false
      };
      setResponseData(errorResult);
      setResponseStatus('error');
      setResponseMessage('Network Error: ' + error.message);
      setIsSuccess(false);
      saveToHistory(currentStep, errorResult, 'error', 'Network Error: ' + error.message, false);
    } finally {
      setIsLoading(false);
    }
  };

  const saveToHistory = (step, response, status, message, success) => {
    const entry = {
      step,
      timestamp: new Date().toISOString(),
      response,
      status,
      message,
      success
    };
    setHistory(prev => {
      const filtered = prev.filter(h => h.step !== step);
      return [...filtered, entry];
    });
  };

  const goToStep = (index) => {
    if (index >= 0 && index < CONVERSATION_STEPS.length) {
      setCurrentStep(index);
    }
  };

  const getProgress = () => {
    return Math.round((completedSteps.size / CONVERSATION_STEPS.length) * 100);
  };

  const addNotification = (message, type = 'success') => {
    const id = Date.now();
    setNotifications(prev => [...prev, { id, message, type }]);
    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== id));
    }, 5000);
  };

  const currentStepData = CONVERSATION_STEPS[currentStep];

  // ============================================
  // RENDER: SMS CONVERSATION
  // ============================================

  const renderSmsConversation = () => {
    if (smsConversation.length === 0) return null;

    return (
      <div className="sms-conversation-container">
        <div className="sms-conversation-header">
          <span className="conversation-title">💬 SMS Conversation</span>
          <span className="conversation-count">{smsConversation.length} messages</span>
        </div>
        <div className="sms-conversation">
          {smsConversation.map((msg) => (
            <div key={msg.id} className={`sms-conversation-bubble ${msg.isSystem ? 'system' : 'user'}`}>
              <div className="sms-sender">{msg.sender}</div>
              <div className="sms-message">{msg.message}</div>
              <div className="sms-time">{msg.timestamp}</div>
            </div>
          ))}
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER: REGISTRATION FLOW
  // ============================================

  const renderRegistrationFlow = () => {
    const step = currentStepData;
    const previewSms = buildSmsMessage(step);
    const isFirstStep = currentStep === 0;
    const isLastStep = currentStep === CONVERSATION_STEPS.length - 1;

    return (
      <div className="registration-container">
        <div className="registration-card">
          {/* Header */}
          <div className="registration-header">
            <div className="registration-icon">{step.icon}</div>
            <h1>PENZI Dating</h1>
            <p className="subtitle">Find your perfect match</p>
          </div>

          {/* Progress Bar */}
          <div className="progress-bar-container">
            <div className="progress-bar">
              <div className="progress-fill" style={{ width: `${getProgress()}%` }}></div>
            </div>
            <span className="progress-text">{getProgress()}% Complete</span>
          </div>

          {/* SMS Conversation */}
          {renderSmsConversation()}

          {/* Step Info */}
          <div className="step-info-card">
            <div className="step-number">Step {currentStep + 1} of {CONVERSATION_STEPS.length}</div>
            <h2>{step.title}</h2>
            <p>{step.subtitle}</p>
          </div>

          {/* Form */}
          <form onSubmit={(e) => { e.preventDefault(); executeApi(); }} className="registration-form">
            {/* Phone Input */}
            {step.requiresPhone && (
              <div className="input-group">
                <label>📱 Your Phone Number</label>
                <input
                  type="text"
                  value={formData.phone || ''}
                  onChange={(e) => handleInputChange('phone', e.target.value)}
                  placeholder="Enter your phone number"
                  className="input-field"
                  required
                />
              </div>
            )}

            {/* Step 1: Activation - Special UI */}
            {isFirstStep && (
              <div className="activation-section">
                <div className="activation-hint">
                  <div className="hint-bubble">
                    <span className="hint-label">📱 To activate:</span>
                    <span className="hint-code">PENZI</span>
                  </div>
                </div>
                <div className="input-group">
                  <label>Enter Activation Code</label>
                  <input
                    type="text"
                    value={formData.input || ''}
                    onChange={(e) => handleInputChange('input', e.target.value)}
                    placeholder="Type PENZI"
                    className="input-field activation-input"
                    required
                  />
                </div>
              </div>
            )}

            {/* Form Fields */}
            {step.inputType === 'form' && step.fields && !isFirstStep && (
              <div className="form-group">
                {step.fields.map((field) => (
                  <div key={field.key} className="field-group">
                    <label>{field.label}</label>
                    {field.type === 'select' ? (
                      <select
                        value={formData[field.key] || ''}
                        onChange={(e) => handleInputChange(field.key, e.target.value)}
                        className="input-field"
                        required={field.required}
                      >
                        <option value="">Select {field.label}</option>
                        {field.options.map(opt => (
                          <option key={opt} value={opt}>{opt}</option>
                        ))}
                      </select>
                    ) : (
                      <input
                        type={field.type || 'text'}
                        value={formData[field.key] || ''}
                        onChange={(e) => handleInputChange(field.key, e.target.value)}
                        placeholder={field.placeholder}
                        className="input-field"
                        required={field.required}
                      />
                    )}
                  </div>
                ))}
              </div>
            )}

            {/* Text Input for Self-Description */}
            {step.inputType === 'text' && !isFirstStep && (
              <div className="input-group">
                <label>{step.inputLabel}</label>
                <textarea
                  value={formData.input || ''}
                  onChange={(e) => handleInputChange('input', e.target.value)}
                  placeholder={step.inputPlaceholder}
                  className="textarea-field"
                  rows={3}
                  required
                />
              </div>
            )}

            {/* SMS Preview */}
            {previewSms && !isFirstStep && (
              <div className="sms-preview-container">
                <div className="sms-preview-label">📱 Your SMS will be:</div>
                <div className="sms-preview-content">{previewSms}</div>
              </div>
            )}

            {/* Action Buttons */}
            <div className="registration-actions">
              <button
                type="button"
                onClick={() => goToStep(currentStep - 1)}
                disabled={currentStep === 0 || isLoading}
                className="btn-secondary"
              >
                ⬅ Previous
              </button>

              <button
                type="submit"
                disabled={isLoading}
                className={`btn-primary ${isLoading ? 'loading' : ''}`}
              >
                {isLoading ? '⏳ Sending...' : isFirstStep ? '💑 Activate Service' : '📤 Send SMS'}
              </button>

              <button
                type="button"
                onClick={() => goToStep(currentStep + 1)}
                disabled={isLastStep || isLoading}
                className="btn-secondary"
              >
                Next ➡
              </button>
            </div>
          </form>

          {/* Response Message */}
          {responseMessage && (
            <div className={`response-message ${isSuccess ? 'success' : 'error'}`}>
              <strong>{isSuccess ? '✅' : '❌'}</strong> {responseMessage}
            </div>
          )}

          {/* Footer */}
          <div className="registration-footer">
            <p>🔒 Your data is safe and private</p>
          </div>
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER: DASHBOARD
  // ============================================

  const renderDashboard = () => {
    return (
      <div className="dashboard-container">
        <header className="dashboard-header">
          <div className="header-left">
            <h1>💑 PENZI</h1>
            <span className="live-badge">❤️ Live</span>
          </div>
          <div className="header-right">
            <span className="user-greeting">👋 {currentUser?.name || 'User'}</span>
            <button className="profile-btn" onClick={() => setShowProfile(!showProfile)}>
              👤
            </button>
          </div>
        </header>

        <nav className="dashboard-nav">
          <button 
            className={`nav-item ${activeTab === 'discover' ? 'active' : ''}`}
            onClick={() => setActiveTab('discover')}
          >
            🔍 Discover
          </button>
          <button 
            className={`nav-item ${activeTab === 'matches' ? 'active' : ''}`}
            onClick={() => setActiveTab('matches')}
          >
            💕 Matches
          </button>
          <button 
            className={`nav-item ${activeTab === 'requests' ? 'active' : ''}`}
            onClick={() => setActiveTab('requests')}
          >
            📬 Requests
          </button>
          <button 
            className={`nav-item ${activeTab === 'chat' ? 'active' : ''}`}
            onClick={() => setActiveTab('chat')}
          >
            💬 Chat
          </button>
        </nav>

        <main className="dashboard-content">
          {activeTab === 'discover' && renderDiscover()}
          {activeTab === 'matches' && renderMatches()}
          {activeTab === 'requests' && renderRequests()}
          {activeTab === 'chat' && renderChat()}
        </main>
      </div>
    );
  };

  // ============================================
  // RENDER: DISCOVER
  // ============================================

  const renderDiscover = () => {
    const sampleMatches = [
      { name: 'Grace Muthoni', age: 28, town: 'Nairobi', profession: 'Nurse', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', description: 'Kind-hearted and adventurous. Loves hiking and reading.' },
      { name: 'James Ochieng', age: 32, town: 'Kisumu', profession: 'Engineer', education: 'Post Graduate', religion: 'Christian', ethnicity: 'Luo', description: 'Ambitious and hardworking. Passionate about technology.' },
      { name: 'Faith Wanjiru', age: 26, town: 'Nakuru', profession: 'Teacher', education: 'Graduate', religion: 'Christian', ethnicity: 'Kikuyu', description: 'Caring and dedicated. Loves children and education.' }
    ];

    const displayMatches = matches.length > 0 ? matches : sampleMatches;
    const currentMatch = displayMatches[currentMatchIndex] || displayMatches[0];

    return (
      <div className="discover-container">
        <div className="match-card">
          <div className="match-card-header">
            <div className="match-avatar">
              {currentMatch?.name?.charAt(0) || '?'}
            </div>
            <div className="match-info">
              <h3>{currentMatch?.name || 'Unknown'}</h3>
              <p>{currentMatch?.age || '?'} years • {currentMatch?.town || 'Unknown'}</p>
            </div>
          </div>

          <div className="match-details">
            <div className="detail-item">
              <span className="detail-label">💼 Profession</span>
              <span className="detail-value">{currentMatch?.profession || 'Not specified'}</span>
            </div>
            <div className="detail-item">
              <span className="detail-label">🎓 Education</span>
              <span className="detail-value">{currentMatch?.education || 'Not specified'}</span>
            </div>
            <div className="detail-item">
              <span className="detail-label">🙏 Religion</span>
              <span className="detail-value">{currentMatch?.religion || 'Not specified'}</span>
            </div>
            <div className="detail-item">
              <span className="detail-label">🌍 Ethnicity</span>
              <span className="detail-value">{currentMatch?.ethnicity || 'Not specified'}</span>
            </div>
            {currentMatch?.description && (
              <div className="detail-item full-width">
                <span className="detail-label">💭 About Me</span>
                <span className="detail-value description">{currentMatch.description}</span>
              </div>
            )}
          </div>

          <div className="match-actions">
            <button className="btn-secondary" onClick={() => setShowMatchDetails(true)}>
              👤 View Profile
            </button>
            <button className="btn-primary">
              💕 I'm Interested
            </button>
          </div>

          <div className="match-navigation">
            <button 
              className="nav-btn"
              onClick={() => setCurrentMatchIndex(Math.max(0, currentMatchIndex - 1))}
              disabled={currentMatchIndex === 0}
            >
              ⬅ Previous
            </button>
            <span className="match-counter">
              {currentMatchIndex + 1} of {displayMatches.length}
            </span>
            <button 
              className="nav-btn"
              onClick={() => setCurrentMatchIndex(Math.min(displayMatches.length - 1, currentMatchIndex + 1))}
              disabled={currentMatchIndex === displayMatches.length - 1}
            >
              Next ➡
            </button>
          </div>
        </div>
      </div>
    );
  };

  // ============================================
  // RENDER: MATCHES
  // ============================================

  const renderMatches = () => {
    return (
      <div className="empty-state">
        <div className="empty-icon">💕</div>
        <h2>No Matches Yet</h2>
        <p>Start discovering and expressing interest to find your match</p>
        <button className="btn-primary" onClick={() => setActiveTab('discover')}>
          Discover People
        </button>
      </div>
    );
  };

  // ============================================
  // RENDER: REQUESTS
  // ============================================

  const renderRequests = () => {
    return (
      <div className="empty-state">
        <div className="empty-icon">📬</div>
        <h2>No Requests</h2>
        <p>When someone shows interest, you'll see it here</p>
      </div>
    );
  };

  // ============================================
  // RENDER: CHAT
  // ============================================

  const renderChat = () => {
    return (
      <div className="empty-state">
        <div className="empty-icon">💬</div>
        <h2>No Messages</h2>
        <p>Start a conversation with your matches</p>
      </div>
    );
  };

  // ============================================
  // MAIN RETURN
  // ============================================

  return (
    <div className="app">
      {isLoggedIn ? renderDashboard() : renderRegistrationFlow()}
    </div>
  );
}

export default App;
